/**
 * Bundles the island manifest into the engine without a bundler feature (SPEC T3).
 *
 * Reads worlds/founding-island/world.toml and writes src/sim/islandManifest.generated.ts,
 * which exports the file's text as a string constant. The engine modules stay plain
 * TypeScript, so they load the same under Node type-stripping, Vite and Vitest.
 * Runs automatically before `npm run build` and `npm run test`; a test also fails if the
 * generated file ever drifts from the TOML.
 *
 * Usage: npm run manifest
 */
import { readFileSync, writeFileSync } from 'node:fs';

const source = new URL('../worlds/founding-island/world.toml', import.meta.url);
const target = new URL('../src/sim/islandManifest.generated.ts', import.meta.url);

const text = readFileSync(source, 'utf8');
const out =
  '// GENERATED by scripts/build-manifest.mjs from worlds/founding-island/world.toml. Do not edit;\n' +
  '// change the TOML and run `npm run manifest` (it also runs before build and test).\n' +
  `export const ISLAND_MANIFEST_TOML = ${JSON.stringify(text)};\n`;

let current = '';
try {
  current = readFileSync(target, 'utf8');
} catch {
  // first run
}
if (current !== out) writeFileSync(target, out);
console.log(`islandManifest.generated.ts ${current === out ? 'is up to date' : 'written'} (${text.length} bytes of TOML)`);
